"""Pages of trades."""


def page_count(n_items, page_size):
    """Return how many pages are needed to show n_items, page_size to a page."""
    return n_items // page_size


def page(trades, number, page_size):
    """Return page `number` of trades. Pages are numbered from 1."""
    start = (number - 1) * page_size
    return trades[start:start + page_size]


def all_pages(trades, page_size):
    """Return every page of trades, in order."""
    return [page(trades, n, page_size) for n in range(1, page_count(len(trades), page_size) + 1)]


def desk_names(trades):
    """Return the distinct desk values, in first-seen order."""
    names = []
    for x in trades:
        if x.desk not in names:
            names.append(x.desk)
    return names

